/bin/bash -lc "python3 - <<'PY'
import ast,copy,hashlib,json
from pathlib import Path
p=Path('/workspace');r=json.load(open(p/'runtime_resolved.json'));q=json.load(open(p/'proposal.json'))
def validate(x,s,path='"'$'"'):
 t=s.get('type');types={'object':dict,'array':list,'string':str,'boolean':bool}
 if t: assert isinstance(x,types[t]),(path,t,type(x).__name__)
 if 'const' in s: assert x==s['const'],path
 if 'enum' in s: assert x in s['enum'],path
 if isinstance(x,str) and 'minLength' in s: assert len(x)>=s['minLength'],path
 if isinstance(x,list):
  assert len(x)>=s.get('minItems',0),path
  for i,v in enumerate(x): validate(v,s.get('items',{}),f'{path}[{i}]')
 if isinstance(x,dict):
  assert set(s.get('required',[]))<=set(x),(path,'missing required')
  props=s.get('properties',{})
  if s.get('additionalProperties') is False: assert set(x)<=set(props),(path,'additional keys')
  for k,v in x.items():
   if k in props: validate(v,props[k],f'{path}.{k}')
validate(q['study'],r['study_schema'])
assert q['parent_trial'] in r['context']['allowed_observation_ids']
assert q['study']['protocol_ref']==r['required_study_protocol_ref']
assert 1<=len(q['variants'])<=4
assert len({x['name'] for x in q['variants']})==len(q['variants'])
assert any(x['role']=='candidate' for x in q['variants'])
allowed={'torch','numpy','math','typing','copy','functools','collections','itertools','dataclasses','contextlib','unirank','model_zoo'}
parent=ast.parse((p/'history_g2_r0000_target_early.py').read_text())
def ctor(tree): return next(n for n in ast.walk(tree) if isinstance(n,ast.FunctionDef) and n.name=='__init__')
def allocations(tree):
 return [ast.dump(n,include_attributes=False) for n in ast.walk(ctor(tree)) if isinstance(n,ast.Call) and ((isinstance(n.func,ast.Attribute) and isinstance(n.func.value,ast.Name) and n.func.value.id=='nn') or (isinstance(n.func,ast.Name) and n.func.id=='FeatureEmbeddingDict'))]
normal=None
for v in q['variants']:
 file=v['file'];assert Path(file).name==file and file.endswith('.py')
 src=(p/file).read_text();tree=ast.parse(src);compile(src,file,'exec')
 cfg=next(n.value for n in tree.body if isinstance(n,ast.Assign) and any(isinstance(t,ast.Name) and t.id=='CONFIG' for t in n.targets))
 assert ast.literal_eval(cfg)==v['config'],file
 assert allocations(tree)==allocations(parent),(file,'module allocations changed')
 tree_without_cfg=copy.deepcopy(tree)
 tree_without_cfg.body=[n for n in tree_without_cfg.body if not(isinstance(n,ast.Assign) and any(isinstance(t,ast.Name) and t.id=='CONFIG' for t in n.targets))]
 dump=ast.dump(tree_without_cfg,include_attributes=False)
 if normal is None: normal=dump
 else: assert normal==dump,(file,'unexpected code difference')
 for n in ast.walk(tree):
  if isinstance(n,(ast.Import,ast.ImportFrom)):
   names=[a.name for a in n.names] if isinstance(n,ast.Import) else [n.module]
   assert all(name.split('.')[0] in allowed for name in names),(file,names)
  if isinstance(n,ast.Call) and isinstance(n.func,ast.Name): assert n.func.id not in {'open','eval','exec','__import__','compile'},file
 print(file,'syntax/config/imports/allocation OK','sha256='+hashlib.sha256(src.encode()).hexdigest())
assert all(x in q['study']['evidence_refs'] for x in r['context']['allowed_observation_ids'])
assert {v['name'] for v in q['variants']}=={'uniform_summary','content_only','counts_only','no_history'}
print('Prospective study schema and proposal references OK; all ancestor evidence retained.')
print('Tensor execution unavailable: no PyTorch. Forward/backward/invariance and host training remain explicitly pending.')
PY"

